    {

           using var activity =  StartCallActivity("StartGroupCallScreenSharingAsync", typeof(StartGroupCallScreenSharing).FullName ?? "StartGroupCallScreenSharingAsync");

           try
           {
             return client.StartGroupCallScreenSharingAsync(groupCallId, audioSourceId, payload);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
